<script setup lang="ts">
import {ref,computed,nextTick,onMounted,onUnmounted} from 'vue';
import Icon from './Icon.vue';
type Project={id:number;name:string;description:string|null;version:number;archived_at:string|null;cover_attachment_id:number|null};
type FileRow={id:number;name:string;bytes:number;preview_url:string|null;download_url:string};
type Credential={id:number;name:string;kind:string;address:string|null;username:string|null;notes:string|null};
const props=defineProps<{projectId:number;csrf:string;disabled:boolean}>();
const emit=defineEmits<{updated:[{id:number;name:string;cover_url:string|null}];working:[boolean]}>();
const opened=ref(false),busy=ref(false),error=ref(''),notice=ref(''),tab=ref('about'),record=ref<Project|null>(null),files=ref<FileRow[]>([]),credentials=ref<Credential[]>([]);
const title=ref(''),description=ref(''),baseline=ref(''),editor=ref(false),editingId=ref<number|null>(null),credentialBaseline=ref('');
const blank=()=>({name:'',kind:'site',address:'',username:'',secret:'',notes:''});const entry=ref(blank());
const confirm=ref<{text:string;action:()=>void}|null>(null),revealed=ref<{id:number;secret:string}|null>(null);
let secretTimeout:ReturnType<typeof setTimeout>|undefined;let opener:HTMLElement|null=null;
const cover=computed(()=>files.value.find(f=>f.id===record.value?.cover_attachment_id));
const dirty=computed(()=>opened.value&&!!record.value&&(JSON.stringify([title.value,description.value])!==baseline.value||(editor.value&&JSON.stringify(entry.value)!==credentialBaseline.value)));
const readOnly=computed(()=>!!record.value?.archived_at);
function hideSecret(){revealed.value=null;if(secretTimeout)clearTimeout(secretTimeout)}
async function request(path='',method='GET',body?:unknown){
 const form=body instanceof FormData;const r=await fetch('/projects/'+props.projectId+path,{method,credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf,...(!form?{'Content-Type':'application/json'}:{})},...(body===undefined?{}:{body:form?body:JSON.stringify(body)})});
 if(r.status===204)return null;const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message||'Не удалось выполнить действие');return d;
}
async function load(){const d=await request('/details');record.value=d.project;files.value=d.files;credentials.value=d.credentials;title.value=d.project.name;description.value=d.project.description||'';baseline.value=JSON.stringify([title.value,description.value]);emit('updated',{id:d.project.id,name:d.project.name,cover_url:d.files.find((f:FileRow)=>f.id===d.project.cover_attachment_id)?.preview_url||null})}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;emit('working',true);error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'Нет соединения с сервером'}finally{busy.value=false;emit('working',false)}}
function payload(extra:Record<string,unknown>={}){return {expected_version:record.value?.version,...extra}}
function closeNow(){hideSecret();entry.value=blank();editor.value=false;record.value=null;credentials.value=[];files.value=[];title.value='';description.value='';confirm.value=null;opened.value=false;nextTick(()=>opener?.focus())}
function close(){if(busy.value)return;if(dirty.value)confirm.value={text:'Закрыть проект без сохранения изменений?',action:closeNow};else closeNow()}
function changeTab(value:string){if(busy.value)return;const action=()=>{title.value=record.value?.name||'';description.value=record.value?.description||'';editor.value=false;entry.value=blank();hideSecret();tab.value=value;notice.value='';error.value=''};if(dirty.value)confirm.value={text:'Перейти в другой раздел без сохранения изменений?',action};else action()}
function open(){if(props.disabled)return;opener=document.activeElement as HTMLElement;opened.value=true;record.value=null;error.value='';tab.value='about';run(load).then(()=>nextTick(()=>document.querySelector<HTMLButtonElement>('.project-close')?.focus()))}
function save(){run(async()=>{await request('/details','PATCH',payload({name:title.value,description:description.value}));await load();notice.value='Информация проекта сохранена'})}
function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(file.size>10*1024*1024){error.value='Файл должен быть не больше 10 МБ';input.value='';return;}run(async()=>{const body=new FormData();body.append('file',file);body.append('expected_version',String(record.value?.version));try{await request('/files','POST',body);await load();notice.value='Файл добавлен'}finally{input.value=''}})}
function chooseCover(id:number|null){const action=()=>run(async()=>{await request('/cover','PUT',payload({attachment_id:id}));await load();notice.value=id?'Обложка установлена':'Обложка убрана. Файл сохранён.'});if(dirty.value)confirm.value={text:'Изменить обложку без сохранения изменений описания?',action};else action()}
function removeFile(f:FileRow){confirm.value={text:'Удалить файл «'+f.name+'» из проекта?',action:()=>run(async()=>{await request('/files/'+f.id,'DELETE',payload());await load();notice.value='Файл удалён'})}}
function edit(c?:Credential){hideSecret();editingId.value=c?.id??null;entry.value=c?{name:c.name,kind:c.kind,address:c.address||'',username:c.username||'',secret:'',notes:c.notes||''}:blank();credentialBaseline.value=JSON.stringify(entry.value);editor.value=true;nextTick(()=>document.querySelector<HTMLInputElement>('#project-access-name')?.focus())}
function cancelEdit(){const action=()=>{editor.value=false;entry.value=blank()};if(dirty.value)confirm.value={text:'Отменить изменения записи доступа?',action};else action()}
function saveCredential(){run(async()=>{await request('/credentials'+(editingId.value?'/'+editingId.value:''),editingId.value?'PATCH':'POST',payload(entry.value));entry.value=blank();editor.value=false;await load();notice.value='Запись доступа сохранена'})}
function removeCredential(c:Credential){hideSecret();confirm.value={text:'Удалить запись доступа «'+c.name+'»?',action:()=>run(async()=>{await request('/credentials/'+c.id,'DELETE',payload());await load();notice.value='Запись удалена'})}}
function reveal(c:Credential){if(revealed.value?.id===c.id){hideSecret();return;}hideSecret();run(async()=>{const d=await request('/credentials/'+c.id+'/reveal','POST');revealed.value={id:c.id,secret:d.secret||''};secretTimeout=setTimeout(hideSecret,60000)})}
async function copySecret(){if(!revealed.value)return;try{await navigator.clipboard.writeText(revealed.value.secret);notice.value='Скопировано в буфер обмена'}catch{error.value='Не удалось скопировать. Можно выделить и скопировать значение вручную.'}}
function safeLink(address:string|null):string|null{try{const url=new URL(address||'');return ['https:','http:'].includes(url.protocol)&&!url.username&&!url.password?url.href:null}catch{return null}}
function key(e:KeyboardEvent){if(e.key==='Escape'){e.stopPropagation();if(confirm.value)confirm.value=null;else close()}if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll<HTMLElement>('.project-dialog button:not(:disabled),.project-dialog input:not(:disabled),.project-dialog textarea:not(:disabled),.project-dialog select:not(:disabled),.project-dialog a[href]')).filter(el=>el.getClientRects().length&&!el.closest('fieldset:disabled'));const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
function visibility(){if(document.hidden)hideSecret()}
onMounted(()=>{window.addEventListener('beforeunload',unload);document.addEventListener('visibilitychange',visibility)});
onUnmounted(()=>{hideSecret();entry.value=blank();window.removeEventListener('beforeunload',unload);document.removeEventListener('visibilitychange',visibility)});
</script>
<template>
<button :disabled="disabled" @click="open"><Icon name="project"/> О проекте</button>
<div v-if="opened" class="overlay project-overlay" @click.self="close" @keydown="key">
<section class="project-dialog" role="dialog" aria-modal="true" aria-labelledby="project-dialog-title" :aria-busy="busy">
<header class="project-dialog-header"><div><small class="muted">Информация проекта</small><h2 id="project-dialog-title">{{record?.name||'Загрузка проекта…'}}</h2></div><button class="project-close" aria-label="Закрыть проект" :disabled="busy" @click="close">×</button></header>
<nav v-if="record" class="task-tabs" aria-label="Разделы проекта"><button v-for="t in [{key:'about',name:'О проекте'},{key:'files',name:'Файлы · '+files.length},{key:'access',name:'Доступы · '+credentials.length}]" :key="t.key" :class="{active:tab===t.key}" :aria-pressed="tab===t.key" :disabled="busy||!!confirm" @click="changeTab(t.key)">{{t.name}}</button></nav>
<div class="project-dialog-content">
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="project-notice" role="status">{{notice}}</p><p v-if="!record&&!error" class="muted">Загрузка…</p>
<section v-if="confirm" class="extras-confirm" role="alertdialog" aria-modal="true" aria-label="Подтверждение действия"><p>{{confirm.text}}</p><div class="actions"><button @click="confirm=null">Отмена</button><button class="primary" @click="{const action=confirm.action;confirm=null;action()}">Подтвердить</button></div></section>
<template v-if="record"><p v-if="readOnly" class="muted">Проект в архиве. Для изменения сначала восстановите его.</p>
<fieldset :disabled="busy||!!confirm">
<section v-if="tab==='about'">
<img v-if="cover?.preview_url" class="project-cover" :src="cover.preview_url" alt="Обложка проекта" loading="lazy">
<div v-if="!readOnly" class="project-cover-actions"><button v-if="cover" type="button" @click="chooseCover(null)">Убрать обложку</button><button type="button" @click="changeTab('files')">{{cover?'Изменить обложку':'Добавить обложку'}}</button></div>
<form @submit.prevent="save"><fieldset :disabled="readOnly"><label>Название проекта<input v-model="title" required maxlength="120"></label><label>Описание и информация<textarea v-model="description" rows="9" maxlength="30000" placeholder="Цель проекта, важные ссылки, договорённости и полезная информация…"></textarea></label><div class="actions"><span class="muted project-save-state">{{dirty?'Есть несохранённые изменения':'Все изменения сохранены'}}</span><button class="primary">Сохранить</button></div></fieldset></form>
</section>
<section v-else-if="tab==='files'"><h3>Файлы проекта</h3><p class="muted">До 50 файлов по 10 МБ. Общий лимит файлов задач и проектов — 250 МБ на аккаунт. Первое изображение станет обложкой.</p><label v-if="!readOnly">Добавить файл<input type="file" accept=".pdf,.txt,.csv,.jpg,.jpeg,.png,.webp,.gif,.zip,.doc,.docx,.xls,.xlsx" @change="upload"></label><p v-if="!files.length" class="muted">Файлов пока нет.</p>
<article v-for="f in files" :key="f.id" class="project-file"><img v-if="f.preview_url" :src="f.preview_url" alt="" loading="lazy"><Icon v-else name="attachment" :size="24"/><div class="project-file-info"><a :href="f.download_url">{{f.name}}</a><small>{{Math.max(1,Math.ceil(f.bytes/1024))}} КБ <span v-if="f.id===record.cover_attachment_id">· Обложка</span></small></div><div v-if="!readOnly" class="actions"><button v-if="f.preview_url&&f.id!==record.cover_attachment_id" @click="chooseCover(f.id)">На обложку</button><button v-if="f.id===record.cover_attachment_id" @click="chooseCover(null)">Убрать обложку</button><button class="danger" @click="removeFile(f)">Удалить</button></div></article>
</section>
<section v-else><div class="project-access-heading"><h3>Доступы к сайтам и серверам</h3><button v-if="!editor&&!readOnly" class="primary" @click="edit()">＋ Доступ</button></div><p class="muted">Пароли зашифрованы в базе и скрыты при открытии проекта. Показанное значение автоматически скроется через минуту.</p>
<form v-if="editor" class="project-access-form" @submit.prevent="saveCredential"><h3>{{editingId?'Изменить доступ':'Новый доступ'}}</h3><div class="two"><label>Название<input id="project-access-name" v-model="entry.name" required maxlength="120" placeholder="Панель хостинга"></label><label>Тип<select v-model="entry.kind"><option value="site">Сайт</option><option value="server">Сервер</option><option value="other">Другое</option></select></label></div><label>Адрес сайта или сервера<input v-model="entry.address" maxlength="500" placeholder="https://example.ru или IP:порт" autocomplete="off" spellcheck="false"></label><div class="two"><label>Логин<input v-model="entry.username" maxlength="240" autocomplete="off" spellcheck="false"></label><label>{{editingId?'Новый пароль / ключ (пусто — сохранить прежний)':'Пароль / ключ'}}<input v-model="entry.secret" type="password" maxlength="20000" autocomplete="new-password"></label></div><label>Примечание<textarea v-model="entry.notes" rows="3" maxlength="10000" placeholder="Порт SSH, расположение проекта, назначение доступа…"></textarea></label><div class="actions"><button type="button" @click="cancelEdit">Отмена</button><button class="primary">Сохранить доступ</button></div></form>
<p v-if="!credentials.length&&!editor" class="muted">Добавьте первый доступ к сайту или серверу.</p>
<article v-for="c in credentials" :key="c.id" class="project-access"><div class="project-access-heading"><h3>{{c.name}}</h3><small>{{{site:'Сайт',server:'Сервер',other:'Другое'}[c.kind as 'site'|'server'|'other']}}</small></div><p v-if="c.address"><span class="muted">Адрес: </span><a v-if="safeLink(c.address)" :href="safeLink(c.address)!" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">{{c.address}}</a><span v-else>{{c.address}}</span></p><p v-if="c.username"><span class="muted">Логин: </span>{{c.username}}</p><p v-if="c.notes" class="project-notes">{{c.notes}}</p>
<div v-if="revealed?.id===c.id" class="project-secret"><pre>{{revealed.secret||'Пароль или ключ не указан'}}</pre><button v-if="revealed.secret" @click="copySecret">Скопировать</button></div><div class="actions"><button :disabled="editor" @click="reveal(c)">{{revealed?.id===c.id?'Скрыть пароль / ключ':'Показать пароль / ключ'}}</button><button v-if="!readOnly" :disabled="editor" @click="edit(c)">Изменить</button><button v-if="!readOnly" class="danger" :disabled="editor" @click="removeCredential(c)">Удалить</button></div></article>
</section></fieldset></template>
</div><footer class="project-dialog-footer"><span class="muted">{{busy?'Сохранение / загрузка…':dirty?'Есть несохранённые изменения':'Информация доступна владельцу проекта'}}</span><button :disabled="busy" @click="close">Закрыть</button></footer>
</section></div>
</template>
